# content_scrn.py — 65호 SCRN 원고 본문(2026-11-19 작성, 11/21 제목 교체). 수치는 numbers_scrn.json에서만. [@key] = 번호 인용(등장순).
#  ★제목: 시리즈 틀(229 districts·Age-standardized) 금지, 쌍점 금지. 단독 저자 무인칭. Results 숫자만, Discussion 숫자 없음. 영국식 철자.
#  ★결과 정의 = 예방 서비스 이용(수검), 질병 아님. screening_uptake 공변량 제외 명시. 격차 작음(SUR P90/P10 1.11) 과장 금지.
#  ★체육 변수: 주모형 일부 credible이나 KH II–IV에서 모두 소실 → '일관된 연관 근거 없음'. 소실 변수에 '강건' 금지. 역방향(걷기·마을체육시설)은 사후 해석만.
#  ★잔차 Moran 양측: I > 기대값, p<0.001 → 양의 잔차 자기상관 남음(과평활 아님). Spatial+·RSR 전부 표에 게재.
import os, json
HERE = os.path.dirname(os.path.abspath(__file__)); N = json.load(open(os.path.join(HERE, "numbers_scrn.json")))
def th(x, d=0): return f"{x:,.{d}f}"
def ci(t, lab=True): return f"{t[0]:.3f} (95% CrI {t[1]:.3f}–{t[2]:.3f})" if lab else f"{t[0]:.3f} ({t[1]:.3f}–{t[2]:.3f})"
def m(k, src="main", lab=True): return ci(N[src][k], lab)
def ph(a, c, lab=False): return ci(N["ph"][f"{a}|{c}"], lab)
U = N["uptake"]; MV = N["mv"]; RM = N["resid_moran"]
def rng(k, srcs): v = [N[s][k][0] for s in srcs]; return f"{min(v):.3f}–{max(v):.3f}"
KH = ("KH_typeI", "KH_typeII", "KH_typeIII", "KH_typeIV")
TITLE = "Persistent small-area gaps in uptake of Korea's organised health check-up among eligible adults"
assert ":" not in TITLE and "229" not in TITLE and "standardi" not in TITLE.lower()
import pandas as _pd
from decimal import Decimal, ROUND_HALF_UP
def r2(x): return str(Decimal(str(x)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
_GI = _pd.read_csv(os.path.join(HERE, "gi_scrn.csv")); _SE = _GI[_GI.sido == "Seoul"].SUR
SEOUL_SUR = (r2(_SE.median()), r2(_SE.quantile(.1)), r2(_SE.quantile(.9))); SUR_MIN = r2(min(v for _, v in N["sur_bottom"])); SUR_MAX = r2(max(v for _, v in N["sur_top"]))
def pp(orr, p0=0.75): o = p0 / (1 - p0) * orr; return 100 * (o / (1 + o) - p0)
KEYWORDS = "Mass screening; Health check-up; Preventive health services; Healthcare disparities; Small-area analysis; Spatio-temporal analysis; Republic of Korea"
RUNNING = "District uptake of the Korean health check-up"
seoul = N["seoul_cold_bym"]; sn = N["seoul_n"]

ABSTRACT = [
("Objectives", "To describe where uptake of Korea's national general health check-up among eligible adults is lower or higher than expected, and whether physical activity, health behaviours, care access and household and social characteristics of districts are associated with it."),
("Setting", f"All {N['n_districts']} districts of the Republic of Korea, 2011–2024, under the National Health Insurance Service general health screening programme."),
("Methods", f"Ecological panel of first-stage attendees among {N['elig_total_m']:.1f} million eligible persons summed over years. Expected attendees were standardised for sex. Bayesian spatio-temporal binomial models related uptake to 12 district characteristics and 5 adjustments, with covariate-subset, Knorr-Held space-time and spatial-confounding checks."),
("Results", f"National uptake was {U['2011']}% in 2011, {U['2017']}% in 2017, {U['2020']}% in 2020 and {U['2024']}% in 2024. District standardised uptake ratios ranged from {N['sur_p10']:.2f} to {N['sur_p90']:.2f} (10th–90th percentile). Ten of {N['gi_cold']} local cold spots were in Seoul, including Gangnam and Jongno, and industrial cities such as Ulsan and Geoje had high ratios. Uptake was lower where more older adults lived alone (odds ratio per 1 SD {m('alone_elderly', lab=False)}, 95% credible interval), an association retained in space-time and spatial-confounding models but not with an intrinsic autoregressive district effect alone or in 2019–2024 alone. Physical activity indicators showed no consistent association."),
("Conclusions", "District differences in uptake were small but persistent, with clusters of lower uptake in Seoul. The association with older adults living alone was model-dependent and may identify districts for closer study rather than individuals for outreach."),
]

INTRO = [
"General health checks offered to asymptomatic adults are widespread in East Asia, although trials in Western populations have not shown that they reduce mortality [@liss2021general]. Korea runs one of the largest programmes: the National Health Insurance Service invites insured adults to a biennial general health screening (annual for non-office workers) that measures blood pressure, glucose, lipids, renal and liver function and chest radiography, and links the results to its national database [@cheolseong2017data]. Participation has been associated with fewer later atherosclerotic events and deaths among those screened [@suh2017impact], and workers' examinations are mandated under occupational health law [@kim2017first; @kang2017current; @eom2017effectiveness].",
"Who attends matters for both equity and the interpretation of the programme's results. In Korean surveys of cancer screening, people chose between the organised national programme and opportunistic private screening, with higher education and income favouring opportunistic screening [@kang2014factors; @hahm2017why; @luu2023socioeconomic], and employment status shaped participation in cancer screening [@kim2016impact; @shim2019employment] and in the national health screening [@lee2026occupational]. Older people with little social contact are less likely to attend community check-ups in Japan [@yamaguchi2018sociodemographic], non-attendance there predicts later loss of independence [@igarashi2019nonparticipation], and social isolation has been associated with non-adherence to cancer screening in the United States [@sedani2025social]. Hart's inverse care law describes how the availability of good care varies inversely with need [@hart1971inverse], and organised programmes can still show persistent geographical variation in uptake [@chiou2014changes].",
"The closest area study, a cross-sectional analysis of the 229 districts in 2019 and 2020, found that the fall in participation during the COVID-19 pandemic was larger where older, less educated populations with poorer access to care lived [@kim2023regional]; national participation in the health screening fell from 2019 to 2020 [@kim2026impact], as did participation in cancer screening [@park2022impact]. That analysis covered 2 years with a geographically weighted regression; it did not follow uptake among eligible adults over a long period, through the 2019 extension of eligibility to younger dependants [@web:mohw2018youth] and the pandemic, with models that separate persistent district differences from yearly change, nor ask whether physical activity, which may cluster with other health-seeking behaviours [@tabuchi2015determinants], is associated with attendance.",
"This study used 14 years of national screening statistics to describe where uptake of the general health check-up among eligible adults is lower or higher than expected after standardisation for sex, and to examine whether physical activity, health behaviours, care access and household and social characteristics of districts are associated with it.",
]

METHODS = [
("Design, setting and outcome",
 f"This ecological panel study [@morgenstern1995ecologic] covered all {N['n_districts']} districts (si, gun and gu) of the Republic of Korea from 2011 to 2024 ({th(N['n_rows'])} district-years) and is reported according to the STROBE statement, with the checklist provided as a supplementary file [@vonelm2007strengthening]. The outcome was uptake of the first-stage National Health Insurance Service general health screening, defined as attendees divided by eligible persons, published by district, sex and year [@web:kosis2026scrn]. The denominator was therefore the eligible population, not attendees. Eligible persons are employees (every 2 years for office workers, every year for non-office workers), heads of self-employed households and household members and dependants aged 40 years or older, and Medical Aid beneficiaries, with invitations to most groups by birth-year parity; from 2019, dependants and household members aged 20–39 years were added [@web:mohw2018youth]. Screening in 2020 could be completed until June 2021 because of the COVID-19 pandemic [@web:mohw2020extension]. This outcome is the use of a preventive service, not a disease.",
 f"Before modelling, the data were checked against national totals: district sums equalled the national eligible and attendee counts in every year, Sejong (published only as a province row from 2012) was taken from that row, and city districts were combined by summing counts. Eligible persons rose by 10.0% in 2018, when the published table changed, for reasons the table does not document, and by 10.8% in 2019 with the extension of eligibility; analyses were therefore also run separately for 2011–2017 and 2018–2024 and for 2019–2024 alone. Ages of eligible persons are not published for districts, so expected attendees were obtained by indirect standardisation for sex [@inskip1983methods]: each district's eligible men and women were multiplied by national uptake for men and women in the same year. The district standardised uptake ratio (SUR) was observed over expected attendees. Because national uptake for each year defines the expectation, estimates refer to uptake relative to the national level of that year."),
("District characteristics",
 "Twelve characteristics in 4 groups were specified before modelling, with expected directions (Supplementary Table S1). Physical activity was represented by the age-standardised walking and moderate-or-higher physical activity rates from the Korea Community Health Survey [@kang2015korea] and by public and village sports facilities per 100,000 residents, expected to be higher where health-seeking behaviour clusters. Health behaviours were current smoking, high-risk drinking and self-reported obesity. Care access was internal-medicine specialists per 100,000 residents and the unmet healthcare need rate [@ko2016unmet]. Household and social characteristics were the basic livelihood security recipient rate, the share of tertiary-educated adults and the share of older adults living alone. Five adjustments were forced into every model: urban-zone population share, physicians per 1000 residents, sex ratio, fiscal autonomy and the share of residents aged 80 years or older, the last standing in for the unpublished age structure of eligible persons. The district screening uptake indicator used as a covariate in related analyses (screening_uptake) was excluded because it is the outcome itself. Characteristics were standardised to 1 SD; self-reported obesity, not surveyed in 2019, was interpolated within districts, and variance inflation factors were reported but no characteristic was dropped (Supplementary Table S1). Hit-and-run accidents, a traffic culture index and fires were negative-control exposures [@lipsitch2010negative]."),
("Statistical analysis",
 f"Attendees were modelled as binomial counts of eligible persons with the logit of the expected uptake as the offset, a Besag-York-Mollié 2 district effect on a contact graph of 593 neighbouring pairs [@besag1991bayesian; @riebler2016intuitive], a first-order random walk and independent year effects, and penalised complexity priors [@simpson2017penalising], fitted with integrated nested Laplace approximation (R-INLA 25.10.19, 1 thread) [@rue2009approximate] in R 4.6.0 [@web:rcore2026]. Among the plain binomial, beta-binomial and binomial with an observation-level random effect, the last was chosen by the widely applicable information criterion (WAIC) in models with the adjustments only ({th(N['lik']['binomial_olre'], 1)} vs {th(N['lik']['binomial'], 1)}); the beta-binomial did not converge within 61 minutes and was not used. Because the observation-level effect absorbs structured variation, WAIC was not used to choose among spatial structures. Effects are odds ratios (ORs) per 1 SD with 95% credible intervals (CrIs); a CrI excluding 1 (judged on unrounded values) is called credible. Characteristics, their grouping and the robustness rules were fixed in a file whose SHA-256 hash was recorded before any model was fitted.",
 "Robustness was assessed in 5 prespecified ways. First, 200 models used random subsets of the 12 characteristics, always with the 5 adjustments [@steegen2016increasing]. Second, Knorr-Held space-time interaction types I–IV were added [@knorrheld2000bayesian]; an association was treated as robust only if it remained credible in all 4. Type I, an independent district-year effect, duplicates the observation-level effect in this design and therefore adds little. Third, spatial confounding was examined with Spatial+ [@dupont2022spatial] and restricted spatial regression, and both are reported whatever their results. Fourth, the principal model was refitted with province-by-year effects, lagged characteristics, alternative neighbour graphs and without the 80-or-over adjustment, and with a population-based alternative offset built from resident population by sex and 16 age groups [@web:mois2026population], which mixes eligibility and uptake and is not an age standardisation of eligible persons. Fifth, analyses were repeated for 2011–2017, 2018–2024, 2019–2024 and without 2020–2021, and, for 2017–2024 only, with manufacturing employment share added as a marker of annual workplace examinations. After the results were seen, between-district and within-district components were separated [@bell2015explaining] and further covariates were added (labelled post hoc). Residual spatial autocorrelation was tested with a 2-sided Moran's I permutation test (999 permutations; smallest attainable P = 0.001) against its expected value; local hot and cold spots of the 14-year log SUR used the Getis-Ord Gi* statistic without correction for multiple testing (exploratory) [@ord1995local].",
 "The Institutional Review Board of Hongik University approved the study (7002340-202511-HR-012; continuing review 7002340-202611-HR-040) and waived informed consent because only published aggregate statistics were used."),
]

def sido_list(d, k=4):
    it = sorted(d.items(), key=lambda x: -x[1])[:k]; return ", ".join(f"{a} {b}" for a, b in it)
RESULTS = [
("Uptake over time and across districts",
 f"Over 2011–2024, {N['scr_total_m']:.1f} million first-stage attendances were recorded among {N['elig_total_m']:.1f} million eligible persons summed over years, in which the same person can appear in several years (Table 1). National uptake rose from {U['2011']}% in 2011 to {U['2017']}% in 2017, fell to {U['2019']}% in 2019 as eligible persons increased from {N['elig_m']['2017']} million to {N['elig_m']['2019']} million, dropped to {U['2020']}% in 2020 and was {U['2024']}% in 2024 (Figure 1C). Uptake was higher in men than in women in every year ({N['uptake_men']['2024']}% vs {N['uptake_women']['2024']}% in 2024).",
 f"District SURs over 14 years ranged from {SUR_MIN} to {SUR_MAX} (10th–90th percentile {N['sur_p10']:.2f}–{N['sur_p90']:.2f}; ratio {N['p90p10']:.2f}; yearly ratios {min(N['p90p10_year'].values()):.2f}–{max(N['p90p10_year'].values()):.2f}), and crude uptake from {N['up_min']:.1f}% to {N['up_max']:.1f}% (10th–90th percentile {N['up_p10']:.1f}%–{N['up_p90']:.1f}%). Seoul districts had a median SUR of {SEOUL_SUR[0]} (10th–90th percentile {SEOUL_SUR[1]}–{SEOUL_SUR[2]}). The lowest SURs were in Ulleung, Wando, Gangnam, Jongno, Yeongdeok and Yongsan and the highest in Dong-gu and Buk-gu of Ulsan, Geoje, Yuseong, Jincheon and Ongjin (Figure 1A). Pooled SURs were spatially autocorrelated (Moran's I {N['obs_moran'][0]:.2f}, P = 0.001); autocorrelation of yearly SURs declined from {N['moran_2011']:.2f} in 2011 to {N['moran_2024']:.2f} in 2024, and district rankings were persistent (Kendall's W {N['kendall_w']:.2f}; Spearman correlation between 2011 and 2024, {N['rho_2011_2024']:.2f}). Gi* identified {N['gi_hot']} hot spots ({sido_list(N['gi_hot_sido'])}) and {N['gi_cold']} cold spots ({sido_list(N['gi_cold_sido'])}). In the principal model, the residual district effect (an odds ratio conditional on the characteristics) was credibly below 1 in {N['bym_coldspot']} districts, including {seoul} of the {sn} Seoul districts, and above 1 in {N['bym_hotspot']} (Figure 1B)."),
("District characteristics",
 f"In the principal model (Table 2), uptake was lower where more older adults lived alone (OR {m('alone_elderly')}; about {abs(pp(N['main']['alone_elderly'][0])):.1f} percentage points at 75% uptake), and higher with more tertiary-educated adults ({m('tertiary')}) and public sports facilities ({m('public_fac')}). Walking ({m('walking')}), village sports facilities ({m('village_fac')}), high-risk drinking ({m('drinking')}) and unmet need ({m('unmet')}) were negatively and internal-medicine specialists ({m('im_spec')}) positively associated; moderate physical activity, smoking, obesity and the livelihood recipient rate were not. Several of these ORs were of the same size as those of the negative controls. The district effect was mostly structured (φ {N['phi_ci'][0]:.2f}, 95% CrI {N['phi_ci'][1]:.2f}–{N['phi_ci'][2]:.2f}), and residual Moran's I was {RM[0]:.3f} against an expected {RM[1]:.4f} (2-sided P = 0.001), indicating remaining positive spatial autocorrelation, so CrIs may be too narrow.",
 f"The older-adults-living-alone association was credible in all {MV['alone_elderly'][2]} subset models containing it, in Knorr-Held types I–IV ({rng('alone_elderly', KH)}), with Spatial+ ({m('alone_elderly', 'D1_spatial_plus', False)}), restricted spatial regression ({m('alone_elderly', 'RSR', False)}), province-by-year effects ({m('alone_elderly', 'C4_sido_year_iid', False)}), without the 80-or-over adjustment ({m('alone_elderly', 'sens_s2', False)}) and with the population-based alternative offset ({m('alone_elderly', 'E_pop', False)}), and, post hoc, both between districts ({ph('P4_between_within', 'ext__living_alone_elderly__B')}) and within districts over time ({ph('P4_between_within', 'ext__living_alone_elderly__W')}; Figure 2). It was not credible with an intrinsic conditional autoregressive district effect alone ({m('alone_elderly', 'icar_besag', False)}) or when 2019–2024 was analysed alone ({ph('P6_2019_2024_only', 'ext__living_alone_elderly')}), and it was weaker in 2020–2024 than in 2011–2019 (ratio of ORs {m('alone_elderly', 'covid_x', False)}).",
 f"None of the physical activity indicators remained credible in Knorr-Held types II–IV (walking {rng('walking', KH[1:])}; public sports facilities {rng('public_fac', KH[1:])}; Table 2; Figure 2). Restricted spatial regression, which forces the district effect to be orthogonal to the characteristics and so approaches a model without a district effect, changed several estimates: public sports facilities {m('public_fac', 'RSR', False)}, walking {m('walking', 'RSR', False)}, moderate physical activity {m('mpa', 'RSR', False)} and village sports facilities {m('village_fac', 'RSR', False)}. Public sports facilities were also not credible in 2019–2024 ({ph('P6_2019_2024_only', 'ext__public_sport_fac_per100k')}). Post hoc, the tertiary-educated share was positive within districts over time ({ph('P4_between_within', 'tertiary_educated_share__W')}) but negative between districts ({ph('P4_between_within', 'tertiary_educated_share__B')}), and negative with restricted spatial regression ({m('tertiary', 'RSR', False)}) and in 2019–2024 ({ph('P6_2019_2024_only', 'tertiary_educated_share')}). In 2017–2024, manufacturing employment share was positively associated with uptake ({ph('P7b_2017_2024_plus_manufacturing', 'manufacturing_share')}). Two of 3 negative controls were credible (traffic culture index {m('traffic_culture_index', 'nc', False)}; fires {m('fires_per_10000', 'nc', False)}). Full results of all alternative models are in Supplementary Tables S2–S5c."),
]

DISCUSSION = [
"### Main findings",
"Across 14 years, uptake of the national general health check-up among eligible adults varied only modestly between districts, but the pattern was persistent: lower uptake clustered in Seoul, especially its affluent and central districts, and in some remote island and coastal counties, while uptake was highest in industrial cities and in parts of the central and southwestern provinces. Of the characteristics examined, only the share of older adults living alone was associated with lower uptake in all space-time and spatial-confounding models, but not with an intrinsic autoregressive district effect alone, more weakly in 2020–2024 and not when the period after the extension of eligibility was analysed alone; it is therefore model-dependent. Physical activity indicators showed no consistent association with attendance.",
"### Interpretation",
"The low uptake in Gangnam, Seocho, Yongsan, Jongno and Jung-gu, together with the negative between-district association of tertiary education, runs against the gradient usually expected for preventive care. In Korean surveys of cancer screening, more educated and wealthier adults were more likely to use opportunistic, privately arranged screening than the organised programme [@kang2014factors; @hahm2017why; @luu2023socioeconomic]; if the same applies to general check-ups, private check-ups not recorded as programme attendance would lower apparent uptake in these districts. This ecological study cannot test that explanation or exclude registration effects, and lower attendance in affluent districts should not be read as less screening.",
"The high uptake in Ulsan, Geoje, Gwangyang and similar cities, and the positive association of manufacturing employment, is consistent with the legal requirement for annual workplace examinations of non-office workers and with the role of occupation in participation [@kang2017current; @lee2026occupational]. A district share of older adults living alone is not individual isolation, and most eligible persons are of working age; the association may reflect older, less employed district populations as much as isolation. It is nevertheless consistent with individual studies in which older people with little social contact attended community check-ups less often [@yamaguchi2018sociodemographic] and social isolation was associated with non-adherence to cancer screening [@sedani2025social], and non-attendance at check-ups has predicted later dependency [@igarashi2019nonparticipation]. Its weakening in 2020–2024 and absence in 2019–2024 alone are compatible with the change in the eligible population in 2019, the pandemic [@kim2023regional; @kim2026impact] and a shorter period, which cannot be separated here.",
"The hypothesis that physical activity is associated with attendance was not supported. Walking and village sports facilities were associated in the opposite direction to that expected and public sports facilities in the expected direction, but these small associations were sensitive to the space-time structure and to restricted spatial regression, and facilities per resident are inflated where populations are shrinking. Interpretation of these post hoc patterns is speculative, and nothing can be inferred about individual physical activity and attendance.",
"### Strengths and limitations",
"Strengths include the use of the eligible population as the denominator, complete national coverage reconciled to national totals over 14 years, a covariate set fixed before modelling, and reporting of all structural and spatial-confounding checks regardless of their results. The study is ecological, and district associations do not describe individuals [@morgenstern1995ecologic]. Eligible persons are not published by age, so standardisation was for sex only; the 80-or-over adjustment and the population-based alternative offset addressed age only indirectly. Eligibility changed in 2018–2019 and screening periods were extended during the pandemic, so yearly uptake is not strictly comparable across these years. The share of older adults living alone was highly collinear with the share aged 80 years or older (variance inflation factor 18.7), although its association persisted without that adjustment. Eligible persons by insurance type are not published for districts, so differences in the mix of annually and biennially eligible persons could explain part of the geography. Positive residual spatial autocorrelation remained, so CrIs may be too narrow, and 2 negative controls were associated with uptake, suggesting possible residual bias. Workplace examinations are counted where insured persons are registered, and opportunistic private check-ups are not observed. The outcome and its denominator were rebuilt from the published tables, whereas the characteristics came from a fixed analysis copy of a district database compiled from public statistics.",
"### Conclusions",
"Uptake of Korea's national general health check-up among eligible adults differed only modestly between districts but persistently, with clusters of lower uptake in Seoul. Districts with more older adults living alone had lower uptake in most models, which may identify districts for closer study rather than individuals for outreach. Recording private check-ups alongside programme attendance would help to show who is actually missed by health screening.",
]
